{"query": "
-- ============================================================
-- STEP 1: Create the security audit result tables
-- ============================================================

-- Drop if exists (idempotent)
DROP TABLE IF EXISTS security_audit_details;
DROP TABLE IF EXISTS security_audit_results;

CREATE TABLE security_audit_results (
    audit_id SERIAL PRIMARY KEY,
    audit_type VARCHAR(50) NOT NULL,
    total_issues INTEGER NOT NULL,
    users_affected INTEGER NOT NULL,
    tables_affected INTEGER NOT NULL
);

CREATE TABLE security_audit_details (
    detail_id SERIAL PRIMARY KEY,
    username VARCHAR(50) NOT NULL,
    issue_type VARCHAR(50) NOT NULL,
    table_name VARCHAR(50),
    permission_type VARCHAR(20),
    expected_access BOOLEAN NOT NULL
);

SELECT 'Tables created successfully' AS status;
"}
